function relatedJurisprudenceLinks(entry){const tags=(entry.topic||'').split(' · '),links=[];const add=(href,label,step=null)=>{if(!links.some(x=>x.href===href))links.push({href,label,step});};if(tags.some(tag=>/medidas de protección/i.test(tag)))add('#laboratorio','Practicar medidas de protección');if(tags.some(tag=>/competencia|excepciones/i.test(tag)))add('#recorrido','Competencia y excepciones',14);else if(tags.some(tag=>/procedimiento contencioso/i.test(tag)))add('#recorrido','Sometimiento a la Corte',10);else if(tags.some(tag=>/procedimiento del caso/i.test(tag)))add('#recorrido','Inicio del proceso ante la Corte',11);if(tags.some(tag=>/responsabilidad estatal|deber de investigar/i.test(tag)))add('#recorrido','Examen de fondo',7);if(tags.some(tag=>/reparaciones|cumplimiento/i.test(tag)))add('#recorrido','Reparaciones y cumplimiento',17);if(!links.length&&!tags.some(tag=>/derecho comparado/i.test(tag)))add('#recorrido','Examinar el fondo',7);return links.slice(0,2);}
function parseDocumentCitation(query) {
  const cleaned = normalizeSearch(query).replace(/[\u2013\u2014\u2212]/g, '-');
  const opinion = cleaned.match(/^oc\s*[-.]?\s*0*(\d+)(?:\s*\/\s*(\d{2}|\d{4}))?$/);
  if (opinion) return {kind:'opinion', number:Number(opinion[1]), year:opinion[2]};
  const judgment = cleaned.match(/^serie\s*c[\s.-]*(?:(?:n(?:o|um)?[.\s]*(?:[\u00ba\u00b0]\s*)?)\s*)?0*(\d+)$/);
  return judgment ? {kind:'judgment', number:Number(judgment[1])} : null;
}

function citationMatchesOpinion(citation, opinion) {
  return citation.number === opinion.number &&
    (!citation.year || String(opinion.year).endsWith(citation.year));
}
function renderJurisprudencia(){const q=normalizeSearch(jurisSearch.value),topic=jurisTopicFilter.value,citation=parseDocumentCitation(q);const filtered=jurisprudencia.filter(x=>(activeJuris==='Todas'||x.jurisdiction===activeJuris)&&(!topic||(x.topic||'').split(' · ').includes(topic))&&(citation?.kind==='judgment'?Number(x.series)===citation.number:!q||normalizeSearch([x.title,x.jurisdiction,x.topic,String(x.series||'')].join(' ')).includes(q)));jurisCount.textContent=filtered.length+' referencias'+(filtered.length===1?'':' encontradas')+(topic?' · tema: '+topic:'')+'.';jurisGrid.innerHTML=filtered.length?filtered.map(x=>'<article class="juris-card"><span class="juris-kind">'+escape(x.jurisdiction)+'</span><h3>'+escape(x.title)+'</h3><p>'+escape(x.topic||'Referencia incluida en el material académico del proyecto.')+'</p><div class="juris-meta">'+(x.series?'Serie C n.º '+escape(x.series):'Consulta institucional')+'</div><div class="juris-connection">Conectar con: '+relatedJurisprudenceLinks(x).map(link=>'<a href="'+link.href+'" '+(link.step===null?'':'data-open-step="'+link.step+'"')+'>'+escape(link.label)+' →</a>').join(' · ')+'</div><a href="'+escape(x.url)+'" target="_blank" rel="noopener noreferrer">'+escape(x.sourceLabel||(x.series?'Abrir sentencia oficial':'Abrir catálogo oficial del caso'))+' ↗</a></article>').join(''):'<p class="juris-empty">No hay coincidencias. Prueba con otro nombre, país o tema.</p>';jurisGrid.querySelectorAll('[data-open-step]').forEach(link=>link.addEventListener('click',event=>{event.preventDefault();openProceduralStep(link.dataset.openStep);}));}
renderJurisFilters();renderJurisprudencia();jurisSearch.addEventListener('input',renderJurisprudencia);jurisTopicFilter.addEventListener('change',renderJurisprudencia);

