function showFocusedPractice(id) {
  const panel = el('focusedPractice');
  const node = id && Object.hasOwn(caseScenarioNodes, id) ? caseScenarioNodes[id] : null;
  panel.hidden = !node;
  if (!node) {
    panel.replaceChildren();
    return null;
  }
  panel.innerHTML = '<p class="section-tag">PR&Aacute;CTICA DE UNA ESTACI&Oacute;N</p><h3 id="focusedPracticeHeading">' + escape(node.title) + '</h3>' +
    '<p>' + escape(node.context) + '</p><fieldset class="stage-challenge"><legend>' + escape(node.prompt) + '</legend>' +
    '<div class="stage-challenge-options">' + node.options.map((option, index) =>
      '<button type="button" data-practice-answer="' + index + '" aria-pressed="false">' + escape(option.text) + '</button>').join('') + '</div>' +
    '<p class="stage-check-feedback" aria-live="polite">Elige una respuesta para ver la explicaci&oacute;n.</p></fieldset>' +
    '<div class="focused-practice-links"><a href="#recorrido?paso=' + (node.stage + 1) + '">Volver a la estaci&oacute;n ' + (node.stage + 1) + '</a>' +
    '<a href="' + escape(node.source) + '" target="_blank" rel="noopener noreferrer">' + escape(node.sourceLabel) + ' &nearr;</a>' +
    '<a href="#caseSimulationTitle">Ir al simulador completo</a></div>';
  const feedback = panel.querySelector('.stage-check-feedback');
  const answers = [...panel.querySelectorAll('[data-practice-answer]')];
  answers.forEach((button, index) => button.addEventListener('click', () => {
    const option = node.options[index];
    answers.forEach(answer => {
      const selected = answer === button;
      answer.setAttribute('aria-pressed', String(selected));
      answer.classList.toggle('is-correct', selected && option.correct);
      answer.classList.toggle('is-wrong', selected && !option.correct);
    });
    feedback.className = 'stage-check-feedback ' + (option.correct ? 'is-correct' : 'is-wrong');
    feedback.textContent = (option.correct ? 'Bien razonado. ' : 'Revisa esta decisi\u00f3n. ') + option.feedback;
  }));
  return panel;
}

function filterRouteTarget(page, params) {
  if (page.id === 'biblioteca' && params.has('norma')) {
    const record = normRecords.find(item => item.id === params.get('norma'));
    if (!record) return null;
    normQuery.value = 'Art. ' + record.article;
    normInstrument.value = record.instrument;
    renderNormLibrary();
    return el('norm-' + record.id).querySelector('h4');
  }
  if (page.id === 'recorrido' && /^\d+$/.test(params.get('paso') || '')) {
    const step = Number(params.get('paso')) - 1;
    if (step < 0 || step >= stages.length) return null;
    selectProceduralStep(step);
    return el('stepDetail');
  }
  if (page.id === 'opiniones' && /^\d+$/.test(params.get('oc') || '')) {
    const number = Number(params.get('oc'));
    if (!opinions.some(item => item.number === number)) return null;
    opinionSearch.value = 'OC-' + String(number).padStart(2, '0');
    activeOpinionPeriod = 'Todas';
    opinionEnglishOnly.checked = false;
    renderOpinionFilters();
    renderOpinions();
    return opinionGrid.querySelector('.opinion-card');
  }
  if (page.id === 'jurisprudencia' && params.has('caso')) {
    const title = params.get('caso');
    if (!jurisprudencia.some(item => item.title === title)) return null;
    jurisSearch.value = title;
    activeJuris = 'Todas';
    jurisTopicFilter.value = '';
    renderJurisFilters();
    renderJurisprudencia();
    return [...jurisGrid.querySelectorAll('.juris-card')].find(card => card.querySelector('h3').textContent === title);
  }
  return null;
}
function showRouteFromHash(fromNavigation=false){const [hash, query]=location.hash.slice(1).split('?');let target=hash?document.getElementById(hash):null;let page=target?.matches('[data-route-page]')?target:target?.closest('[data-route-page]');if(!page)page=document.getElementById('inicio');routePages.forEach(section=>{section.hidden=section!==page;});const params=new URLSearchParams(query);const focused=showFocusedPractice(page.id==='arcadia'?params.get('decision'):null);if(focused)target=focused;else if(query)target=filterRouteTarget(page,params)||target;markSection(page.id);const matchingMenuLink=sidebarLinks.find(a=>a.hash==='#'+page.id)||sidebarLinks.find(a=>a.hash==='#'+hash);if(matchingMenuLink){const activeGroup=matchingMenuLink.closest('[data-nav-group]');document.querySelectorAll('[data-nav-group]').forEach(group=>{group.open=group===activeGroup;});}setMenu(false,false);requestAnimationFrame(()=>{if(target&&target!==page)target.scrollIntoView({block:'start'});else window.scrollTo({top:0,behavior:'auto'});if(fromNavigation){const heading=target&&target!==page?(target.matches('h1,h2,h3,h4')?target:target.querySelector('h1,h2,h3,h4')):page.querySelector('h1,h2,h3,h4');if(heading){if(!heading.hasAttribute('tabindex'))heading.setAttribute('tabindex','-1');heading.focus({preventScroll:true});}}if(pendingSearchFocus){const input=el('atlasSearch');input?.scrollIntoView({block:'center',behavior:'smooth'});input?.focus({preventScroll:true});pendingSearchFocus=false;}});}
