const admissibilityState={step:0,route:null,answers:[],locked:false};
function activeAdmissibilityStep(){const step=admissibilityState.step;if(step===0)return admissibilitySteps.find(item=>item.id==='competence');if(step===1)return admissibilitySteps.find(item=>item.id==='remedies');if(step===2)return admissibilitySteps.find(item=>item.id===(admissibilityState.route==='exhausted'?'sixMonths':admissibilityState.route==='exception'?'reasonableTime':'risk'));if(step===3)return admissibilitySteps.find(item=>item.id==='duplication');if(step===4)return admissibilitySteps.find(item=>item.id==='characterization');return null;}
function renderAdmissibility(){const prompt=el('admissibilityPrompt'),choices=el('admissibilityChoices'),result=el('admissibilityResult'),next=el('admissibilityNext'),step=activeAdmissibilityStep();admissibilityState.locked=false;next.hidden=true;if(!step){const correct=admissibilityState.answers.filter(answer=>answer.correct).length;el('admissibilityProgress').textContent='Recorrido terminado · '+correct+' de '+admissibilityState.answers.length+' decisiones bien razonadas';prompt.textContent='Tu lectura del expediente';choices.innerHTML='';result.innerHTML='<strong>Ruta elegida: '+(admissibilityState.route==='exhausted'?'recursos agotados':admissibilityState.route==='exception'?'excepción al agotamiento':'posible falta de agotamiento')+'.</strong> Has revisado competencia, recursos internos, regla temporal, duplicación y caracterización. La admisibilidad no decide todavía si hubo una violación ni sustituye el análisis del fondo.';next.hidden=true;return;}el('admissibilityProgress').textContent='Decisión '+(admissibilityState.step+1)+' de 5 · '+(admissibilityState.answers.filter(answer=>answer.correct).length)+' respuestas correctas';prompt.textContent=step.prompt;choices.innerHTML=step.choices.map((choice,index)=>'<button type="button" data-admissibility-choice="'+index+'">'+escape(choice.text)+'</button>').join('');result.textContent='Elige una respuesta. La explicación y la regla aplicable aparecerán aquí.';choices.querySelectorAll('[data-admissibility-choice]').forEach(button=>button.addEventListener('click',()=>{if(admissibilityState.locked)return;admissibilityState.locked=true;const choice=step.choices[Number(button.dataset.admissibilityChoice)];if(step.id==='remedies')admissibilityState.route=choice.route;else admissibilityState.answers.push({correct:choice.correct});choices.querySelectorAll('button').forEach((option,index)=>{option.disabled=true;const answer=step.choices[index];option.classList.add(step.id==='remedies'?(option===button?'chosen':'neutral'):answer.correct?'chosen':option===button?'incorrect':'neutral');});result.innerHTML='<strong>'+(step.id==='remedies'?'Ruta registrada.':choice.correct?'Regla identificada.':'Revisa este punto.')+'</strong> '+escape(choice.feedback)+' <a href="'+escape(step.source)+'" target="_blank" rel="noopener noreferrer">'+escape(step.label)+' ↗</a> <a href="#recorrido" data-open-step="'+step.stage+'">Repasar la estación relacionada →</a>'+(step.id==='sixMonths'?' <a href="#reloj" data-open-clock>Probar la fecha de ejemplo en el reloj de plazos &rarr;</a>':'');result.querySelector('[data-open-step]').addEventListener('click',event=>{event.preventDefault();openProceduralStep(event.currentTarget.dataset.openStep);});const clockLink=result.querySelector('[data-open-clock]');if(clockLink)clockLink.addEventListener('click',()=>{el('clockRule').value='0';el('clockStart').value='2024-01-15';calc();});next.hidden=false;next.textContent=admissibilityState.step===4?'Ver síntesis →':'Siguiente decisión →';}));}
function resetAdmissibility(){admissibilityState.step=0;admissibilityState.route=null;admissibilityState.answers=[];renderAdmissibility();}
el('admissibilityNext').addEventListener('click',()=>{admissibilityState.step++;renderAdmissibility();});el('admissibilityReset').addEventListener('click',resetAdmissibility);renderAdmissibility();

