const glossary=window.RI_GLOSARIO||[],glossarySearch=el('glossarySearch'),glossaryFilters=el('glossaryFilters'),glossaryGrid=el('glossaryGrid'),glossaryCount=el('glossaryCount'),glossaryPopover=el('glossaryPopover');
